import java.util.Scanner;

public class RaizCuadradaNewton {
    public static void main(String[] args) {
        Scanner teclado = new Scanner(System.in);
        System.out.print("Numero: ");
        double s = teclado.nextDouble();

        if (s < 0) {
            System.out.println("Error: no existe raiz cuadrada real.");
        } else {
            double x = s / 2.0; // Aproximacion inicial
            double anterior = 0;
            int iteraciones = 0;

            while (Math.abs(x - anterior) > 0.0001) {
                anterior = x;
                x = (x + s / x) / 2;
                iteraciones++;
            }

            System.out.printf("Raiz cuadrada de %.4f = %.6f%n", s, x);
            System.out.println("Iteraciones: " + iteraciones);
            System.out.printf("Comprobacion: %.6f * %.6f = %.6f%n", x, x, x * x);
        }

        teclado.close();
    }
}

