        // Ejemplo 2: verificar que un array no esta vacio
        String[] nombres = {"Ana", "Carlos"};
        assert nombres.length > 0 : "El array no debe estar vacio";
        System.out.println("Primer nombre: " + nombres[0]);

        // Ejemplo 3: verificar un calculo
        double nota = 7.5;
        double media = (nota + 8.0) / 2;
        assert media >= 0 && media <= 10
            : "La media debe estar entre 0 y 10, valor: " + media;
        System.out.printf("Media: %.2f%n", media);

        System.out.println("Todas las aserciones pasaron.");
    }
