public class MetodosConAssert {

    /**
     * Calcula la nota media de dos calificaciones.
     * Precondiciones: ambas notas deben estar entre 0 y 10.
     */
    public static double calcularMedia(double nota1, double nota2) {
        // Precondiciones: verificar que los datos de entrada son validos
        assert nota1 >= 0 && nota1 <= 10
            : "nota1 fuera de rango: " + nota1;
        assert nota2 >= 0 && nota2 <= 10
            : "nota2 fuera de rango: " + nota2;

        double media = (nota1 + nota2) / 2;

        // Postcondicion: la media debe estar entre 0 y 10
        assert media >= 0 && media <= 10
            : "La media calculada esta fuera de rango: " + media;

        return media;
    }

    public static void main(String[] args) {
        // Caso normal: funciona correctamente
        double media1 = calcularMedia(7.0, 9.0);
        System.out.println("Media 1: " + media1);

        double media2 = calcularMedia(5.5, 6.5);
        System.out.println("Media 2: " + media2);

        // Este caso activaria un AssertionError si las aserciones estan activadas
        // double media3 = calcularMedia(12.0, 5.0); // nota1 > 10
    }
}

