public class AssertRango {
    public static void main(String[] args) {
        double porcentaje = 75.5;

        assert porcentaje >= 0 && porcentaje <= 100
            : "Porcentaje fuera de rango: " + porcentaje;

        System.out.println("Porcentaje valido: " + porcentaje);
    }
}

public class DividirConAssert {
    public static double dividir(double a, double b) {
        // Precondicion: divisor no puede ser cero
        assert b != 0 : "El divisor no puede ser cero";

        double resultado = a / b;

        // Postcondicion: resultado debe ser un numero finito
        assert Double.isFinite(resultado) : "El resultado no es finito: " + resultado;

        return resultado;
    }

    public static void main(String[] args) {
        System.out.println("10 / 2 = " + dividir(10, 2));
        System.out.println("7 / 3 = " + dividir(7, 3));
        // dividir(10, 0) activaria AssertionError con -ea
    }
}

public class BuscarConAssert {
    public static int buscar(int[] array, int objetivo) {
        // Precondiciones
        assert array != null : "El array no puede ser nulo";
        assert array.length > 0 : "El array no puede estar vacio";

        for (int i = 0; i < array.length; i++) {
            if (array[i] == objetivo) {
                // Postcondicion: el indice debe ser valido
                assert i >= 0 && i < array.length
                    : "Indice fuera de rango: " + i;
                return i;
            }
        }
        return -1; // No encontrado
    }

    public static void main(String[] args) {
        int[] numeros = {10, 25, 30, 45, 50};
        int encontrado = buscar(numeros, 30);
        System.out.println("Indice: " + encontrado);

        int noEncontrado = buscar(numeros, 99);
        System.out.println("Indice: " + noEncontrado);
    }
}
